const timelineBuckets = `-- name: TimelineBuckets :many



SELECT to_char(a.local_date, 'YYYY-MM')::text AS month, count(*)::integer AS count
FROM library_assets($1::uuid) a
LEFT JOIN asset_user_state us ON us.asset_id = a.id AND us.user_id = $1::uuid
WHERE a.visibility = 'timeline' AND a.motion_of IS NULL AND ($2::text = '' OR a.type = $2::text)
  AND NOT EXISTS (SELECT 1 FROM stack_assets sa JOIN stacks st ON st.id = sa.stack_id
                  WHERE sa.asset_id = a.id AND st.state = 'confirmed' AND st.cover_asset_id <> a.id)
  AND (cardinality($3::text[]) = 0 OR NOT EXISTS (
        SELECT 1 FROM asset_labels l WHERE l.asset_id = a.id AND l.label = ANY($3::text[]) AND l.basis IN ('metadata', 'visual', 'confirmed')))
  AND coalesce(us.rating, 0) >= $4::integer
  AND ($5::text = '' OR ($5::text = 'unrejected' AND us.flag IS DISTINCT FROM 'reject') OR us.flag = $5::text)
  AND ($6::text = '' OR us.color_label = $6::text)
  AND (NOT $7::boolean OR coalesce(us.favorite, false))
  AND (coalesce(cardinality($8::uuid[]), 0) = 0 OR a.id IN (
        SELECT pi.asset_id FROM person_items pi JOIN people p ON p.id = pi.person_id
        WHERE pi.person_id = ANY($8::uuid[]) AND p.owner_id = $1::uuid
        GROUP BY pi.asset_id HAVING count(DISTINCT pi.person_id) = cardinality($8::uuid[])))
  AND (coalesce(cardinality($9::text[]), 0) = 0 OR a.id IN (
        SELECT ak.asset_id FROM asset_keywords ak JOIN keywords k ON k.id = ak.keyword_id
        WHERE k.owner_id = $1::uuid AND lower(k.name) = ANY($9::text[])))
  AND ($10::date IS NULL OR a.local_date >= $10::date)
  AND ($11::text = '' OR ($11::text = 'mine' AND a.owner_id = $1::uuid)
       OR ($11::text = 'household' AND EXISTS (SELECT 1 FROM space_assets sx WHERE sx.asset_id = a.id)))
  AND ($12::date IS NULL OR a.local_date <= $12::date)
  AND ($13::text = ''
       OR ($13::text = 'ai' AND a.source_type IN ('ai_generated', 'ai_edited'))
       OR ($13::text = 'not_ai' AND a.source_type NOT IN ('ai_generated', 'ai_edited'))
       OR ($13::text = 'camera' AND a.source_type NOT IN ('ai_generated', 'ai_edited', 'screenshot')
           AND EXISTS (SELECT 1 FROM asset_metadata md WHERE md.asset_id = a.id AND (md.make IS NOT NULL OR md.model IS NOT NULL))))
GROUP BY 1
ORDER BY 1 DESC
`

type TimelineBucketsParams struct {
	Viewer    uuid.UUID
	Type      string
	Hide      []string
	MinRating int32
	Flag      string
	Color     string
	Favorite  bool
	People    []uuid.UUID
	Keywords  []string
	After     pgtype.Date
	Library   string
	Before    pgtype.Date
	Source    string
}

type TimelineBucketsRow struct {
	Month string
	Count int32
}

// Reads for a viewer. Every query here goes through the gate: library_assets(viewer) for the
// timeline (your own items and the Household's), visible_assets(viewer) for everything you may see
// (albums shared with you too).
// An item shows on its own in the timeline unless it's a Live Photo's motion clip or a
// non-cover member of a confirmed stack.
// The timeline (and a smart album, which is the timeline narrowed by its rules) can be narrowed
// by the viewer's marks, favorites, people (all of them), keywords (any), a date range, where
// items came from (made with AI, not, or by a camera), and whose library (the viewer's own, or the
// Household's). Each filter is off when empty.
func (q *Queries) TimelineBuckets(ctx context.Context, arg TimelineBucketsParams) ([]TimelineBucketsRow, error) {
	rows, err := q.db.Query(ctx, timelineBuckets,
		arg.Viewer,
		arg.Type,
		arg.Hide,
		arg.MinRating,
		arg.Flag,
		arg.Color,
		arg.Favorite,
		arg.People,
		arg.Keywords,
		arg.After,
		arg.Library,
		arg.Before,
		arg.Source,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TimelineBucketsRow{}
	for rows.Next() {
		var i TimelineBucketsRow
		if err := rows.Scan(&i.Month, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

